insert into public.exercises (owner_id, slug, name, short_name, category, measurement_type, level, instructions, media) values (null, 'sentadilla', 'Sentadilla con barra', 'Sentadilla', 'strength', 'weight_reps', 'intermediate', $j${"tempo": "3 s bajada · 1 s subida", "cues": [{"title": "Pies al ancho de hombros", "body": "Puntas abiertas 15–30°. Aprieta la barra contra la espalda alta antes de sacarla del rack."}, {"title": "Cadera y rodilla a la vez", "body": "Las rodillas siguen la dirección de los pies; no dejes que caigan hacia adentro."}, {"title": "Baja a paralelo o más", "body": "La cadera llega a la altura de la rodilla con el pecho arriba y la espalda neutra."}, {"title": "Empuja el suelo", "body": "Peso en todo el pie; cadera y pecho suben al mismo ritmo."}], "errors": [{"title": "Rodillas hacia adentro", "fix": "Piensa en «abrir el suelo» con los pies durante la subida."}, {"title": "Talones despegados", "fix": "Trabaja movilidad de tobillo o usa calzado con tacón."}, {"title": "Espalda baja que se redondea", "fix": "Baja solo hasta donde mantienes la columna neutra."}], "breath": ["Inhala profundo arriba y bloquea el abdomen", "Mantén el aire durante la bajada", "Exhala al superar el punto más difícil de la subida"], "met": 6}$j$::jsonb, $j$[{"kind": "animation", "ref": "gym-mannequin:squat"}]$j$::jsonb);
