insert into public.exercises (owner_id, slug, name, short_name, category, measurement_type, level, instructions, media) values (null, 'peso-muerto', 'Peso muerto', 'Peso muerto', 'strength', 'weight_reps', 'intermediate', $j${"tempo": "1 s subida · 2 s bajada", "cues": [{"title": "Barra sobre el medio del pie", "body": "Espinillas a 2–3 cm de la barra antes de agacharte."}, {"title": "Bisagra de cadera", "body": "Lleva la cadera atrás hasta agarrar la barra con los brazos rectos."}, {"title": "Saca la holgura", "body": "Tensa los dorsales y tira de la barra sin despegarla todavía."}, {"title": "Empuja y extiende", "body": "Empuja el suelo con las piernas y termina con la cadera, sin hiperextender."}], "errors": [{"title": "Barra lejos del cuerpo", "fix": "Rózala por las piernas durante todo el recorrido."}, {"title": "La cadera sube primero", "fix": "Cadera y hombros deben subir juntos al despegar."}, {"title": "Tirar con los brazos", "fix": "Los brazos son ganchos: no flexiones los codos."}], "breath": ["Inhala y tensa el core antes de cada repetición", "Aguanta el aire al despegar la barra", "Exhala arriba, con la cadera bloqueada"], "met": 6}$j$::jsonb, $j$[{"kind": "animation", "ref": "gym-mannequin:deadlift"}]$j$::jsonb);
