insert into public.exercises (owner_id, slug, name, short_name, category, measurement_type, level, instructions, media) values (null, 'press-banca', 'Press de banca', 'Press banca', 'strength', 'weight_reps', 'beginner', $j${"tempo": "2 s bajada · 1 s subida", "cues": [{"title": "Escápulas atrás y abajo", "body": "Crea un arco natural y apoya firme la espalda alta."}, {"title": "Agarre algo más ancho que los hombros", "body": "Muñecas rectas, la barra sobre el talón de la mano."}, {"title": "Baja a la parte baja del pecho", "body": "Codos a 45–60° del torso, no abiertos a 90°."}, {"title": "Empuja hacia atrás y arriba", "body": "La barra vuelve a la línea de los hombros."}], "errors": [{"title": "Rebotar en el pecho", "fix": "Toca suave y controla la transición."}, {"title": "Glúteos que se levantan", "fix": "Pies firmes y cadera pegada al banco."}, {"title": "Codos muy abiertos", "fix": "Estresa el hombro: ciérralos ligeramente."}], "breath": ["Inhala al bajar la barra", "Mantén la tensión abajo", "Exhala al empujar"], "met": 5}$j$::jsonb, $j$[{"kind": "animation", "ref": "gym-mannequin:bench"}]$j$::jsonb);
