insert into public.exercises (owner_id, slug, name, short_name, category, measurement_type, level, instructions, media) values (null, 'press-militar', 'Press militar', 'Press militar', 'strength', 'weight_reps', 'intermediate', $j${"tempo": "1 s subida · 2 s bajada", "cues": [{"title": "Barra sobre las clavículas", "body": "Codos ligeramente por delante de la barra."}, {"title": "Glúteos y abdomen apretados", "body": "Evita arquear la zona lumbar."}, {"title": "Aparta la cabeza", "body": "Retrae el mentón y empuja en línea recta."}, {"title": "Bloquea arriba", "body": "Barra sobre el medio del pie, cabeza «a través de la ventana»."}], "errors": [{"title": "Arquear la zona lumbar", "fix": "Aprieta glúteos y reduce el peso."}, {"title": "Barra que se va adelante", "fix": "Trayectoria vertical, pegada a la cara."}, {"title": "Impulso de piernas", "fix": "Eso es push press: rodillas fijas."}], "breath": ["Inhala abajo y bloquea el core", "Exhala al pasar la frente", "Vuelve a inhalar arriba antes de bajar"], "met": 5}$j$::jsonb, $j$[{"kind": "animation", "ref": "gym-mannequin:ohp"}]$j$::jsonb);
