insert into public.exercises (owner_id, slug, name, short_name, category, measurement_type, level, instructions, media) values (null, 'curl', 'Curl con barra', 'Curl', 'strength', 'weight_reps', 'beginner', $j${"tempo": "1 s subida · 3 s bajada", "cues": [{"title": "Codos pegados al torso", "body": "Fíjalos a los costados durante todo el movimiento."}, {"title": "Sube sin balancear", "body": "El torso no se mueve; solo trabaja el codo."}, {"title": "Aprieta arriba", "body": "Pausa breve con el bíceps contraído."}, {"title": "Baja controlado", "body": "Extiende casi por completo sin perder tensión."}], "errors": [{"title": "Balancear el cuerpo", "fix": "Reduce el peso o apoya la espalda en una pared."}, {"title": "Codos que avanzan", "fix": "Convierte el curl en un ejercicio de hombro."}, {"title": "Recorrido corto", "fix": "Baja hasta casi extender el brazo."}], "breath": ["Exhala al subir", "Inhala al bajar"], "met": 3.5}$j$::jsonb, $j$[{"kind": "animation", "ref": "gym-mannequin:curl"}]$j$::jsonb);
